const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),number=n=>n<100?n.toFixed(1).replace(/\.0$/,''):Math.round(n).toLocaleString(),skill=id=>data.skills.find(s=>s.id===+id),modeNames={normal:'普通炼化',skills:'技能特化',slots:'插槽特化'};
