function initialize(d,b){data=d;bridge=b;$('guideStart').onclick=start;$('guideStop').onclick=stop;$('guideRefresh').onclick=refresh;$('guideEdit').onclick=()=>bridge.showPage('planner');$('guideOpenInventory').onclick=()=>bridge.showPage('inventory');$('guideResults').onclick=e=>{const toggle=e.target.closest('[data-guide-toggle]');if(toggle){const route=routes[+toggle.dataset.guideToggle];if(!route)return;const open=!expandedRoutes.has(routeKey(route));if(open)expandedRoutes.add(routeKey(route));else expandedRoutes.delete(routeKey(route));toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'收起详情 ↑':'展开详情 ↓';$(toggle.getAttribute('aria-controls'))?.classList.toggle('hidden',!open);return;}const el=e.target.closest('[data-guide-export]');if(!el)return;const route=routes[+el.dataset.guideExport],blob=new Blob([JSON.stringify({application:'Sunbreak Forge Handcraft Guide',version:'0.8.12',request,route},null,2)],{type:'application/json'}),link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download='handcraft-guide-'+(Number(el.dataset.guideExport)+1)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),500);};refresh();}
